const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let page='calendar',month=9,mode='week',current=null,subject=0,selectedWeek=1,gradeFilter='both';
const titles={calendar:['Teaching calendar','Choose a school day to open its lessons and materials.'],maps:['What to teach','The TEKS explained, with a teaching example and what to look for.'],grades:['Friday checks & grades','Check the skill you taught. Save the response and note the help given.'],monitoring:['Student progress','Keep track of the skill, the response and the next teaching step.'],parents:['For families','Explain what children are learning and how they can show it.'],resources:['Teaching materials','Choose materials that help teach this week’s skills.']};
const download=(label,file)=>`<div class="download-group"><a class="download" href="resources/${esc(file)}" download="${esc(file)}" target="_blank" rel="noopener"><span>${esc(label)}</span><span>PDF ↓</span></a><a class="pdf-open" href="resources/${esc(file)}" target="_blank" rel="noopener" aria-label="Open or print ${esc(label)}">Open / print PDF ↗</a></div>`;
const legend=`<div class="legend"><span style="--c:var(--read)">Reading & writing</span><span style="--c:var(--math)">Math</span><span style="--c:var(--science)">Science</span><span style="--c:var(--history)">Social studies</span></div>`;
const dateFormat=(iso,opts={month:'long',day:'numeric',weekday:'long'})=>new Date(iso+'T12:00:00').toLocaleDateString('en-US',opts);
const lessonByDate=Object.fromEntries(LESSONS.map(x=>[x.date,x]));
function switchPage(p){page=p;document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.page===p));$('#pageTitle').textContent=titles[p][0];$('#pageDesc').textContent=titles[p][1];render();document.querySelectorAll('.nav').forEach(x=>x.setAttribute('aria-current',x.dataset.page===p?'page':'false'));$('#content').focus({preventScroll:true});window.scrollTo(0,0);}
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>switchPage(b.dataset.page));
const subjectKeys=['reading','math','science','social'];
const subjectNames=['Reading & writing','Math','Science','Social studies'];
const visibleGrades=()=>gradeFilter==='both'?[3,4]:[Number(gradeFilter)];
function dayCard(iso){
 const l=lessonByDate[iso],day=Number(iso.slice(-2));
 if(!l){let note='Outside this plan';if(['2026-11-02','2026-11-03'].includes(iso))note='Student holiday';if(iso>='2026-11-23'&&iso<='2026-11-27')note='Fall break';return `<div class="off"><span class="date">${day}</span><p>${note}</p></div>`;}
 return `<article class="day ${l.friday?'assess':''}"><button class="daytop" data-date="${iso}" aria-label="Open ${dateFormat(iso)}"><span class="date">${dateFormat(iso,{weekday:'short',day:'numeric'})}</span><span class="weeklabel">W${l.week}</span></button>${l.friday?`<span class="checklabel">${l.experiment?'Experiment + 4 checks':'4 Friday checks'}</span>`:'<span class="checklabel muted">Learn · practice · show</span>'}<div class="day-subjects">${l.subjects.map((s,j)=>`<button class="daily-subject ${subjectKeys[j]}" data-date="${iso}" data-open-subject="${j}"><strong>${subjectNames[j]}</strong>${visibleGrades().map(g=>`<span><b>G${g} · ${esc(s.targets['g'+g].codes.join(' / '))}</b><span class="target-skill">${esc(s.targets['g'+g].skill)}</span></span>`).join('')}<span class="openhint">Open lesson →</span></button>`).join('')}</div></article>`;
}
function weeklySkills(w){const t=w.thematic||{},seasonClass=w.n<=3?'storybook':w.n<=6?'autumn': 'winter';return `<section class="weekly-overview" aria-label="This week’s learning"><div class="week-heading"><div><span class="eyebrow">WEEK ${w.n} · ${esc(w.dates)}</span><h2>${esc(w.theme)}</h2></div><span class="badge">${w.exp?'Science experiment Friday':'Friday checks'}</span></div><article class="weekly-story-card ${seasonClass}"><div class="story-main"><span class="story-label">THIS WEEK’S SHARED READ-ALOUD</span><h3>${esc(t.book||w.books3)}</h3><p>${esc(t.storyFocus||w.bookStoryFocus||'Read together, discuss the story, and use the same book across the week.')}</p></div><div class="story-finish"><b>After comprehension</b><p>${esc(t.craft||w.craft||'Offer a hands-on book connection after students show what they understood.')}</p></div></article></section>`;}
function weekGrid(w){const ls=LESSONS.filter(l=>l.week===w.n),start=new Date(ls[0].date+'T12:00:00');start.setDate(start.getDate()-((start.getDay()+6)%7));let days='';for(let n=0;n<5;n++){const d=new Date(start);d.setDate(d.getDate()+n);days+=dayCard(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`);}return `<div class="calgrid">${days}</div>`;}
function calendarView(){
 let body='';
 if(mode==='month'){const first=new Date(2026,month,1),last=new Date(2026,month+1,0),start=new Date(first);start.setDate(start.getDate()-((start.getDay()+6)%7));let grid='';for(let d=new Date(start);d<=last;d.setDate(d.getDate()+1)){if([0,6].includes(d.getDay()))continue;const iso=`2026-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;grid+=d.getMonth()===month?dayCard(iso):'<div class="blank"></div>';}body=`<div class="calgrid monthgrid">${grid}</div>`;}
 else body=(mode==='week'?[WEEKS[selectedWeek-1]]:WEEKS).map(w=>weeklySkills(w)+weekGrid(w)).join('');
 $('#content').innerHTML=`<div class="toolbar"><div class="toolbar-group"><button id="prevPeriod" class="secondary" aria-label="Previous ${mode==='month'?'month':'week'}" ${(mode==='month'?month===9:selectedWeek===1)||mode==='weeks'?'disabled':''}>‹</button><label class="sr-only" for="weekSelect">Choose week</label>${mode==='month'?`<h2>${new Date(2026,month,1).toLocaleDateString('en-US',{month:'long',year:'numeric'})}</h2>`:`<select id="weekSelect" ${mode==='weeks'?'disabled':''}>${WEEKS.map(w=>`<option value="${w.n}" ${w.n===selectedWeek?'selected':''}>Week ${w.n} · ${esc(w.dates)}</option>`).join('')}</select>`}<button id="nextPeriod" class="secondary" aria-label="Next ${mode==='month'?'month':'week'}" ${(mode==='month'?month===11:selectedWeek===9)||mode==='weeks'?'disabled':''}>›</button></div><div class="segmented" aria-label="Calendar view">${[['week','Week'],['month','Month'],['weeks','Nine weeks']].map(([v,label])=>`<button data-mode="${v}" aria-pressed="${mode===v}" class="${mode===v?'selected':''}">${label}</button>`).join('')}</div></div><div class="calendar-options"><p>Choose a subject on any day to see the lesson and materials.</p><label>Show <select id="gradeFilter"><option value="both">Both grades</option><option value="3">Grade 3</option><option value="4">Grade 4</option></select></label></div>${legend}${body}<p class="section-note">42 school days · October 13–December 18, 2026. November 2–3 and fall break follow the supplied plan. Confirm campus dates.</p>`;
 $('#gradeFilter').value=gradeFilter;$('#gradeFilter').onchange=e=>{gradeFilter=e.target.value;calendarView();};
 $('#prevPeriod').onclick=()=>{if(mode==='month')month--;else selectedWeek--;calendarView();};$('#nextPeriod').onclick=()=>{if(mode==='month')month++;else selectedWeek++;calendarView();};if($('#weekSelect'))$('#weekSelect').onchange=e=>{selectedWeek=Number(e.target.value);calendarView();};
 document.querySelectorAll('[data-mode]').forEach(x=>x.onclick=()=>{const nextMode=x.dataset.mode;if(nextMode==='month')month=Number(LESSONS.find(l=>l.week===selectedWeek).date.slice(5,7))-1;if(mode==='month'&&nextMode==='week')selectedWeek=LESSONS.find(l=>Number(l.date.slice(5,7))===month+1).week;mode=nextMode;calendarView();});document.querySelectorAll('[data-date]').forEach(x=>x.onclick=()=>openLesson(x.dataset.date,Number(x.dataset.openSubject||0)));
}
function weekPicker(){return `<div class="planning-toolbar"><label for="planningWeek">Planning for</label><select id="planningWeek">${WEEKS.map(w=>`<option value="${w.n}" ${w.n===selectedWeek?'selected':''}>Week ${w.n} · ${esc(w.dates)}</option>`).join('')}</select><span class="muted">The same week carries across pages.</span></div>`;}
function standardList(key,codes,exact=true){return `<ul class="standard-list">${codes.map(code=>{const t=TEKS_STANDARDS[key+':'+code];return `<li><span class="teks">${esc(code)}</span><span class="plain-label">In everyday language</span><p>${esc(t.meaning)}</p>${exact?`<details class="wording"><summary>Show actual TEKS wording</summary><p>${esc(t.official)}</p></details>`:''}</li>`;}).join('')}</ul>`;}
function weekSubjects(w,{examples=false,family=false}={}){const first=LESSONS.find(l=>l.week===w.n);return subjectKeys.map((key,j)=>`<section class="planning-subject ${key}"><h2>${subjectNames[j]}</h2><div class="mapbranches">${[3,4].map(g=>`<article class="planning-grade"><span class="grade-label">Grade ${g}</span>${standardList(key,w.skills[key]['g'+g].teks,true)}${examples?`<div class="teaching-example"><b>Teach it with</b><p>${j===0?esc(first.books['g'+g].title):esc(first.subjects[j].materials)}</p><b>One supported step to look for</b><p>${esc(first.subjects[j].targets['g'+g].skill)}</p></div>`:''}</article>`).join('')}</div>${examples?`<button class="primary teach-subject" data-week="${w.n}" data-teach-subject="${j}">Open ${subjectNames[j].toLowerCase()} lesson</button>`:''}</section>`).join('');}
function mapsView(){const w=WEEKS[selectedWeek-1];return `${weekPicker()}<div class="teacher-note"><b>Start with the skill.</b> Read what each TEKS means, then choose the support that lets the student work on it. The book or activity is how you teach the skill.</div>${weekSubjects(w,{examples:true})}<h2>Daily learning sequence</h2><p>These dated targets drive the calendar and downloads. Open a subject to teach that exact day.</p>${LESSONS.filter(l=>l.week===w.n).map(l=>`<details class="map-day"><summary>${dateFormat(l.date)}</summary>${l.subjects.map((s,j)=>`<article><h3>${subjectNames[j]}</h3>${[3,4].map(g=>`<p><b>Grade ${g} · ${esc(s.targets["g"+g].codes.join(" / "))}</b><br>${esc(s.targets["g"+g].skill)}</p>`).join("")}<button class="secondary dated-lesson" data-lesson-date="${l.date}" data-lesson-subject="${j}">Open this lesson</button></article>`).join("")}</details>`).join("")}<details><summary>See the teaching sequence across all nine weeks</summary>${WEEKS.map(w=>`<section class="sequence-week"><h3>Week ${w.n} · ${esc(w.dates)}</h3>${subjectKeys.map((key,j)=>`<h4>${subjectNames[j]}</h4><div class="mapbranches">${[3,4].map(g=>`<div><b>Grade ${g}</b>${standardList(key,w.skills[key]['g'+g].teks)}</div>`).join('')}</div>`).join('')}</section>`).join('')}</details><div class="downloads">${download('TEKS explained · all subjects','teks-reference.pdf')}${download('Complete teaching binder','full-binder.pdf')}</div><details><summary>Pacing and curriculum sources</summary><p>The dates follow the supplied district year-at-a-glance plan. These lessons adapt the standards for hands-on teaching. Use HMH, STEMscopes and McGraw Hill for the matching grade-level lessons, Bridges for placement-selected intervention, and Vizzle for familiar practice.</p><p><a href="${PLAN_META.sources.g3}" target="_blank" rel="noopener">Grade 3 TEKS source</a> · <a href="${PLAN_META.sources.g4}" target="_blank" rel="noopener">Grade 4 TEKS source</a></p></details>`;}
function gradesView(){const w=WEEKS[selectedWeek-1],l=LESSONS.find(l=>l.week===w.n&&l.friday);return `${weekPicker()}<div class="teacher-note"><b>Friday, ${esc(w.fri)}</b> · Three short questions or tasks for spelling, reading, math and science. ${w.exp?'Use the science experiment for this Friday’s science check.':''} Save ${esc(w.extra.toLowerCase())} as the additional product.</div><div class="downloads">${download('This Friday’s questions and answer keys',`week-${w.n}-friday.pdf`)}${download('All planned grades for the nine weeks','grade-register.pdf')}${download('Record scores and support','weekly-grade-evidence.pdf')}</div><section class="planning-subject reading"><h2>Spelling</h2><p>Choose three words from the sound-spelling pattern each student has been taught. Say the word, use it in a sentence, then repeat it. Save the spelling response and note help given. Select the exact HMH spelling skill for each learner; do not assign a TEKS code without that information.</p></section>${subjectKeys.map((key,j)=>`<section class="planning-subject ${key}"><h2>${j===3?'Social studies · '+(w.extra==='Social studies'?'graded product this week':'practice evidence this week'):subjectNames[j]+' check'}</h2><div class="mapbranches">${[3,4].map(g=>`<article class="planning-grade"><span class="grade-label">Grade ${g}</span>${standardList(key,l.subjects[j].targets['g'+g].codes)}<div class="teaching-example"><b>Ask the student to show</b><p>${esc(l.subjects[j].targets['g'+g].skill)}</p><b>Save</b><p>${j===0?'A response to a book question and the page used as evidence.':j===1?'The math model or work sample, with the student’s answer.':j===2?'The prediction, observation and explanation from the check or investigation.':'The source picture, map or short product and the student’s explanation.'}</p></div></article>`).join('')}</div><button class="secondary teach-subject" data-week="${w.n}" data-teach-subject="${j}" data-friday="true">Open Friday ${subjectNames[j].toLowerCase()}</button></section>`).join('')}<section class="teacher-note"><b>Record learning and help separately.</b> Write correct / total, the response method and any extra prompt. Apply the school’s grading rules. A supported classroom task is a step toward the standard; it does not establish mastery of the whole TEKS.</section><details><summary>All planned grade dates · 45 entries per learner</summary><p>23 reading/writing/spelling entries · 9 math · 9 science · 4 social studies. Confirm these proposed entries against campus requirements.</p><div class="grade-schedule"><table><thead><tr><th>Friday</th><th>Checks</th><th>Additional product</th></tr></thead><tbody>${WEEKS.map(w=>`<tr><td>${esc(w.fri)}</td><td>Spelling, reading, math, ${w.exp?'science experiment':'science'}</td><td>${esc(w.extra)}</td></tr>`).join('')}</tbody></table></div></details>`;}
function monitoringView(){const w=WEEKS[selectedWeek-1];return `${weekPicker()}<div class="teacher-note"><b>IEP goals are still needed.</b> The TEKS describe grade-level learning. An IEP goal describes an individual student’s measured target. Add the actual goals before choosing activities for formal IEP progress checks.</div><div class="steps"><div class="step"><strong>Choose the skill</strong><span>Write the subject, TEKS code and plain-English meaning.</span></div><div class="step"><strong>Watch one fresh response</strong><span>Use a new example and the student’s planned response method.</span></div><div class="step"><strong>Record what happened</strong><span>Save correct / total and the help given. Keep no response separate from an incorrect answer.</span></div><div class="step"><strong>Choose the next step</strong><span>Reteach, repeat with less help, or increase the challenge.</span></div></div><h2>This week’s skills to watch</h2>${subjectKeys.map((key,j)=>`<details><summary>${subjectNames[j]} · Week ${w.n}</summary><div class="mapbranches">${[3,4].map(g=>`<div><b>Grade ${g}</b>${standardList(key,w.skills[key]['g'+g].teks)}</div>`).join('')}</div><button class="secondary teach-subject" data-week="${w.n}" data-teach-subject="${j}">See the lesson and response task</button></details>`).join('')}<h2 class="spaced">A useful teacher note</h2><div class="teacher-note"><b>Example · Reading TEKS 3.6G</b><p>The student chose two relevant details and used them to identify the key idea in 2 of 3 trials. Pointing was the planned response; one trial needed an extra verbal prompt. Next time: use another short section with the same supports.</p><p>This is classroom evidence. Count it as an IEP check only when it matches the actual goal and its measurement rules.</p></div><h2>Choose a record</h2><div class="downloads">${download('Add the actual IEP goals and schedule','iep-setup.pdf')}${download('Record responses and help','monitoring-log.pdf')}${download('Track change across nine weeks','goal-trend.pdf')}${download('Track steps in a daily routine','task-analysis.pdf')}</div><details><summary>Simple prompt key</summary><p>I: independent with planned access · V: extra verbal prompt · G: gesture · M: model · P: physical guidance · NR: no response.</p><p>Compare the same skill under similar conditions. Keep the number of trials and response method visible so changes in the task are not mistaken for changes in learning.</p></details>`;}
function parentsView(){const w=WEEKS[selectedWeek-1];return `<div class="teacher-note"><b>A family-friendly explanation:</b> TEKS are the skills Texas students are expected to learn. We teach those skills through real books, hands-on activities and support matched to each child.</div><div class="downloads">${download('Send home · nine-week learning outline','parent-outlines.pdf')}</div>${weekPicker()}<p class="family-books"><b>Books this week:</b> ${esc(w.books3)}${w.books3===w.books4?'':' and '+esc(w.books4)}</p>${weekSubjects(w,{family:true})}<h2>How your child can show learning</h2><p>Children may speak, point, use pictures or AAC, build a model, or write. We record both what they can do and the help they need. Fridays include short spelling, reading, math and science checks; alternate lab Fridays use the investigation as the science check.</p><h2>Optional conversation at home</h2><p>After sharing a book, ask: “Which detail helped you understand?” Let your child point or tell you. Home practice is optional and is not graded.</p><details><summary>Before sending the outline home</summary><p>Add the child’s current learning step, successful response method, helpful supports and next challenge. Add IEP information only after the actual goals have been provided.</p></details>`;}
const resourceGroups=[['Reading & writing','reading',[['Response cards and story mats','response-story-mats.pdf'],['Writing and source-evidence frames','writing-history-frames.pdf']]],['Math','math',[['Equal groups and sharing mat','sharing-mat.pdf'],['Fraction strips','fraction-strips.pdf'],['Array, area and perimeter mat','array-mat.pdf']]],['Science','science',[['Prediction and observation record','science-record.pdf']]],['Social studies','social',[['Source evidence and writing frames','writing-history-frames.pdf']]]];
function resourcesView(){const w=WEEKS[selectedWeek-1];return `${weekPicker()}<div class="teacher-note"><b>Download or open any resource.</b> PDF ↓ saves a copy. Open / print PDF lets you view, print or save it in your browser. If the app preview blocks downloads, open the calendar in Safari or Chrome. <br><b>Choose a material for the skill.</b> Read the TEKS meaning below, open the lesson, then download the mat or record it calls for.</div>${resourceGroups.map(([name,key,files],j)=>`<section class="planning-subject ${key}"><h2>${name}</h2><div class="mapbranches">${[3,4].map(g=>`<div><b>Grade ${g}</b>${standardList(key,w.skills[key]['g'+g].teks)}</div>`).join('')}</div><div class="downloads">${files.map(x=>download(...x)).join('')}${key==='reading'?download('This week’s real-book guide',`week-${w.n}-book-guide.pdf`)+(w.n===1?download('Room on the Broom · classroom printables','room-on-the-broom-classroom-printables.pdf'):''):''}</div><button class="textbtn teach-subject" data-week="${w.n}" data-teach-subject="${j}">See how to use these in the lesson →</button></section>`).join('')}<h2>This week’s printable plan</h2><div class="downloads">${download("Week "+w.n+" teaching map",`week-${w.n}-plan.pdf`)}${download("Week "+w.n+" reading and spelling check",`week-${w.n}-reading-check.pdf`)}${download("Week "+w.n+" Friday checks and keys",`week-${w.n}-friday.pdf`)}</div><h2>Books and investigations</h2><p>This week’s book: ${esc(w.books3)}. Theme: ${esc(w.thematic?.arc||w.theme)} The same book connects each subject.</p><div class="downloads">${download('Book list and props to prepare','book-shopping-list.pdf')}${download('Seasonal books and investigations','seasonal-guide.pdf')}</div><h2 class="spaced">Planning and records</h2><div class="downloads">${[['TEKS explained · all subjects','teks-reference.pdf'],['Daily routine and rotations','routine.pdf'],['All planned grades','grade-register.pdf'],['Weekly scores and evidence','weekly-grade-evidence.pdf'],['IEP goal setup','iep-setup.pdf'],['Progress log','monitoring-log.pdf'],['Progress over nine weeks','goal-trend.pdf'],['Daily routine step record','task-analysis.pdf'],['Choose licensed lessons and spelling words','resource-selector.pdf'],['Family learning outline','parent-outlines.pdf']].map(x=>download(...x)).join('')}</div><details><summary>Print a complete packet</summary><p>These packets use the updated lessons and TEKS explanations.</p><div class="downloads">${download('Complete teaching binder','full-binder.pdf')}${download('Friday checks and progress records','full-assessments.pdf')}${download('Book guides and classroom materials','full-resources.pdf')}</div></details>`;}
function render(){if(page==='calendar')return calendarView();$('#content').innerHTML=({maps:mapsView,grades:gradesView,monitoring:monitoringView,parents:parentsView,resources:resourcesView}[page])();if($('#planningWeek'))$('#planningWeek').onchange=e=>{selectedWeek=Number(e.target.value);render();};document.querySelectorAll('.teach-subject').forEach(x=>x.onclick=()=>openLesson(LESSONS.find(l=>l.week===Number(x.dataset.week)&&(!x.dataset.friday||l.friday)).date,Number(x.dataset.teachSubject)));document.querySelectorAll('.dated-lesson').forEach(x=>x.onclick=()=>openLesson(x.dataset.lessonDate,Number(x.dataset.lessonSubject)));document.querySelectorAll('.openweek').forEach(x=>x.onclick=()=>openLesson(LESSONS.find(l=>l.week===Number(x.dataset.week)).date));document.querySelectorAll('.fridayopen').forEach(x=>x.onclick=()=>openLesson(LESSONS.find(l=>l.week===Number(x.dataset.week)&&l.friday).date));}
const dialog=$('#lessonDialog');function showDialog(html){$('#dialogContent').innerHTML=html;$('#closeDialog').onclick=()=>dialog.close();if(!dialog.open)dialog.showModal();dialog.scrollTop=0;}
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
function openLesson(date,initialSubject=0){current=lessonByDate[date];subject=initialSubject;renderLesson();}
function renderLesson(){const l=current,s=l.subjects[subject],index=LESSONS.indexOf(l),w=WEEKS[l.week-1];
showDialog(`<div class="modalhead"><div><div class="eyebrow">WEEK ${l.week} · ${l.friday?'FRIDAY CHECKS':'DAILY LESSON'} ${l.experiment?'· SCIENCE LAB':''}</div><h2 id="dialogTitle">${dateFormat(l.date)}</h2><span class="muted">${esc(l.theme)}</span></div><button id="closeDialog" class="close" aria-label="Close lesson">×</button></div><div class="modalbody"><div class="subjecttabs" role="group" aria-label="Choose subject">${l.subjects.map((s,i)=>`<button data-subject="${i}" aria-pressed="${subject===i}" class="${subjectKeys[i]} ${subject===i?'selected':''}">${subjectNames[i]}</button>`).join('')}</div><div class="lesson-heading"><h2>The TEKS: what each student needs to learn</h2>${download("This day’s lessons",`day-${l.date}.pdf`)}</div><div class="branchpanel">${[3,4].map(g=>{const t=s.targets['g'+g];return `<div class="grade"><small>GRADE ${g} LEARNER</small>${t.codes.map(code=>{const standard=TEKS_STANDARDS[subjectKeys[subject]+':'+code];return `<section class="standard-block"><h3>${subjectNames[subject]} · TEKS ${esc(code)}</h3><details class="wording"><summary>Show actual TEKS wording</summary><p class="standard-wording">${esc(standard.official)}</p></details><p class="standard-meaning"><b>In plain English</b>${esc(standard.meaning)}</p></section>`;}).join('')}<div class="today-application"><b>Today’s lesson applies this by:</b><p>${esc(t.skill)}</p></div></div>`;}).join('')}</div><p class="section-note">These are supported steps toward the grade-level standards. Use each learner’s response mode and access needs; grade alone does not determine independence.</p>
${subject===0?'':`<div class="book-connection"><b>Today’s book connection:</b> ${esc(s.book||w.books3)} · ${esc(s.bookConnection||w.bookArc||'Use the shared book as the context for the skill.')}</div>`}
${subject===0?`<div class="booknote"><b>Shared read-aloud</b><span>${esc(l.books.g3.title)}${l.books.shared?'':' · '+esc(l.books.g4.title)}</span><small>Both learners use this same book. Keep their targets individual and point to the page or illustration as evidence.</small></div>`:''}
${subject===1?'<div class="status"><b>Same math routine each day:</b> 5 minutes fluency → 3 minutes I Do → 5 minutes We Do → two 10-minute teacher rotations → 5 minutes You Do and record. Each teacher rotation includes the current STEMscopes skill and a short placement-selected Bridges intervention.</div>':''}
${l.friday?'<div class="status"><b>Friday:</b> spelling, reading, math and science checks. Use three short items per check and record help separately. On lab Fridays, the investigation provides the science check evidence.</div>':''}
<div class="lessonflow"><div class="stage">I DO<br><small>3 min</small></div><p>${esc(s.model)}</p><div class="stage">WE DO<br><small>5 min</small></div><p>${esc(s.practice)}</p><div class="stage">YOU DO<br><small>3–5 min</small></div><p>${esc(s.check)}</p></div>
${subject===0?`<div class="status"><b>Writing and spelling:</b> ${esc(s.writing)}</div><div class="status"><b>Visual companion:</b> ${l.books.g3.title.includes('Arnold')?'Use the four-season picture sequence and topic/detail visual cards throughout the read-aloud. Offer pointing, AAC, speech, dictation or the large-print response sheet.':'Use the beginning-middle-end sequence strip and WH picture cards throughout the read-aloud. Offer pointing, AAC, speech, dictation or the large-print response sheet.'}</div><div class="status"><b>Craft or enrichment:</b> ${esc(s.enrichment)}</div><details><summary>Writing TEKS · Grade 3 and Grade 4</summary>${[3,4].map(g=>standardList("reading",s.writingCodes["g"+g])).join("")}</details><details open><summary>Read from the book · questions and evidence</summary>${textHTML(l)}</details>`:''}
${subject===2&&l.seasonalInvestigation?`<section class="labplan"><span class="eyebrow">ALTERNATE-FRIDAY EXPERIMENT</span><h3>Investigate ${esc(l.seasonal?.title||l.books.g3.title)}</h3><p>${esc(l.seasonalInvestigation)}</p><p><b>Record three things:</b> prediction, observation, explanation. Mark each correct/total and note prompts. The experiment is adult-supervised; the other learner uses a separate familiar task.</p></section>`:''}
<h2>Teach one student, then switch</h2><div class="rotation"><div><h3>First rotation · 8–10 minutes</h3><p><b>Teacher:</b> teach the Grade 3 target using the access support below.</p><p><b>Grade 4 learner:</b> use the already-taught independent task.</p></div><div><h3>Second rotation · 8–10 minutes</h3><p><b>Teacher:</b> teach the Grade 4 target using their access support.</p><p><b>Grade 3 learner:</b> use the already-taught independent task.</p></div><div class="wide"><b>Independent work with a clear finish</b><p>${esc(s.independent)} Use a first/then card, a small task tray and a finished basket. Vizzle is a familiar goal-tagged practice option after the task is taught.</p></div></div>
<details><summary>Adapt the lesson to each learner</summary><p><b>When understanding is emerging:</b> ${esc(s.access.starting)}</p><p><b>When a learner hesitates or refuses to respond:</b> ${esc(s.access.response)}</p><p><b>When ready for more:</b> ${esc(s.access.stretch)}</p><p>Use these supports according to the learner’s actual needs, not an assumed link between grade and disability.</p></details>
${l.friday?assessmentHTML(l,subject):''}
<details open><summary>Save evidence · grade · check progress</summary><p>${esc(s.evidence)}</p><p><b>Prompt codes:</b> I independent with planned access · V verbal · G gesture · M model · P physical guidance · NR no response.</p><div class="downloads">${download('Weekly grade evidence','weekly-grade-evidence.pdf')}${download('IEP goal log','monitoring-log.pdf')}</div></details>
<details><summary>Prepare and download materials</summary><p>${esc(s.materials)}</p><div class="downloads">${l.downloads.filter(x=>x.name!=='Today’s lesson card').map(x=>download(x.name,x.file)).join('')}</div></details><details><summary>Core curriculum and TEKS sources</summary><p><b>HMH:</b> current reading/writing unit and taught spelling pattern. <b>STEMscopes:</b> current math target. <b>McGraw Hill:</b> current science concept. <b>Bridges:</b> placement-selected intervention. <b>Vizzle:</b> previously taught, individualized practice. Select exact licensed lessons inside Stacie’s accounts.</p><p>${esc(PLAN_META.alignmentNote)}</p><p><a href="${PLAN_META.sources.g3}" target="_blank" rel="noopener">TEA Grade 3 standards</a> · <a href="${PLAN_META.sources.g4}" target="_blank" rel="noopener">TEA Grade 4 standards</a></p>${download('Licensed lesson selection sheet','resource-selector.pdf')}</details><div class="modalfooter"><button id="previousDay" class="secondary" ${index===0?'disabled':''}>Previous school day</button><button id="nextDay" class="secondary" ${index===LESSONS.length-1?'disabled':''}>Next school day</button></div></div>`);
 document.querySelectorAll('[data-subject]').forEach(x=>x.onclick=()=>{subject=Number(x.dataset.subject);renderLesson();document.querySelector(`[data-subject="${subject}"]`).focus({preventScroll:true});});$('#previousDay').onclick=()=>{current=LESSONS[index-1];renderLesson();};$('#nextDay').onclick=()=>{current=LESSONS[index+1];renderLesson();};
}
function textHTML(l){const t=l.books;return `<div class="qgrid">${[3,4].map(g=>{const b=t['g'+g];return `<div><h3>Grade ${g} · ${esc(b.title)}</h3><p class="muted">${esc(b.author)} · ${esc(b.kind)}</p><p>${esc(b.focus)}</p><p><b>Props:</b> ${esc(b.props)}</p><ol>${t['q'+g].map(q=>`<li>${esc(q)}</li>`).join('')}</ol><details><summary>Teacher answer key</summary><ol>${t['key'+g].map(q=>`<li>${esc(q)}</li>`).join('')}</ol></details>${b.url?`<a href="${esc(b.url)}" target="_blank" rel="noopener">Book information</a>`:''}</div>`;}).join('')}</div><p>Use the actual book and its illustrations. The downloadable guide contains teaching tools, not the book. Borrow a physical copy or use an authorized library/publisher e-book.</p>`;}
function assessmentHTML(l,sub){const a=l.assessment;if(sub===0)return '<details open><summary>Friday spelling</summary><p>Assess three individually taught words selected for each learner’s current sound-spelling pattern. Say each word in a sentence and repeat it. Record independent encoding separately from identifying a taught pattern with support. Use the real-book reading questions above and record the page or scene used as evidence.</p></details>';if(sub===1||sub===2){const pre=sub===1?'math':'sci',key=sub===1?'mathkey':'scikey';return `<details open><summary>${sub===1?'Math':'Science'} Friday tasks ${l.experiment&&sub===2?'during the experiment':''}</summary><div class="qgrid">${[3,4].map(g=>`<div><h3>Grade ${g}</h3><ol>${a[pre+g].map(q=>`<li>${esc(q)}</li>`).join('')}</ol><details><summary>Teacher answer key</summary><p>${esc(a[key+g])}</p></details></div>`).join('')}</div></details>`;}return `<details open><summary>This week’s additional product</summary><p>${esc(l.extra)}. Use the weekly assessment download for the planned product criteria. Use district social studies sources for the history branch.</p></details>`;}
function routineHTML(){return `<h3>8–9 AM · the same opening every day</h3><p class="section-note">Suggested times within Stacie’s confirmed first hour. Adjust library travel time once, then keep the sequence predictable.</p><div class="routine"><div><b>8:00</b><span>7 minutes yoga</span></div><div><b>8:07</b><span>Library visit and return</span></div><div><b>8:25</b><span>Feelings check-in</span></div><div><b>8:32</b><span>Preview today’s learning</span></div><div><b>8:37</b><span>Weekly read-aloud, response and transition</span></div></div><h3 class="spaced">Math · repeat this 38-minute sequence</h3><div class="steps"><div class="step"><strong>5 min · Fluency</strong><span>Previously taught counting, facts or number recognition. Extend to 10 minutes if the block allows.</span></div><div class="step"><strong>8 min · Model and guide</strong><span>3 minutes I Do, 5 minutes We Do with today’s STEMscopes skill.</span></div><div class="step"><strong>20 min · Rotate</strong><span>10 minutes each: about 6 minutes grade-level skill + 4 minutes Bridges intervention. Other student completes mastered work or known Vizzle practice.</span></div><div class="step"><strong>5 min · Show and record</strong><span>Fresh response, help used, finished basket and next-block preview.</span></div></div><p>Bridges lessons may require a longer block; preserve the program’s lesson structure and schedule additional intervention time when needed. Campus times for later subjects are still to be set.</p><h3>Other subjects</h3><p>Shared start → I Do → We Do → teach the first student while the second practices → switch → You Do → record and reset. Preview any Friday change with the same visual schedule.</p>${download('Daily routine and rotations','routine.pdf')}`;}
$('#routineBtn').onclick=()=>showDialog(`<div class="modalhead"><h2 id="dialogTitle">Daily routine</h2><button id="closeDialog" class="close" aria-label="Close">×</button></div><div class="modalbody">${routineHTML()}</div>`);
$('#helpBtn').onclick=()=>showDialog(`<div class="modalhead"><h2 id="dialogTitle">Use the calendar</h2><button id="closeDialog" class="close" aria-label="Close">×</button></div><div class="modalbody"><div class="steps"><div class="step"><strong>1 · Choose a day</strong><span>Click a school day in the calendar.</span></div><div class="step"><strong>2 · Choose a subject</strong><span>Read what the TEKS means, then the lesson and teaching steps.</span></div><div class="step"><strong>3 · Pull the materials</strong><span>Download the book guide, math mat or science record.</span></div><div class="step"><strong>4 · Teach and record</strong><span>Rotate, check a fresh response, save evidence.</span></div></div><p>Friday cards identify the four checks. Experiment labels identify alternate-Friday labs. Use the navigation for what to teach, Friday checks, student progress, family information and materials.</p><p>Download buttons provide focused PDFs saved with this calendar. Daily lessons are proposed adaptations grounded in the supplied YAG. Enter actual IEP requirements and choose licensed lessons inside Stacie’s accounts.</p></div>`);
render();

const themeButton=$('#themeBtn');
try {document.documentElement.dataset.theme=localStorage.getItem('stacie-planner-theme')||'light';}catch{}
function syncTheme(){themeButton.textContent=document.documentElement.dataset.theme==='light'?'Dark mode':'Light mode';}
themeButton.onclick=()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='light'?'dark':'light';try{localStorage.setItem('stacie-planner-theme',document.documentElement.dataset.theme);}catch{}syncTheme();};syncTheme();
